from 写入第二遍 import add
add('24_002',2,'16:9，武士伏地头背的中近景，巨体占满中央与下幅，头压在下缘，远处云天较亮；固定机位，整体维持浅景深虚焦，轮廓只留模糊厚重形。','武士仍伏在碎坑里，头与双臂没有抬起；一缕米灰薄尘贴着背侧散过去，晨光在圆弧背缘慢慢铺开一条柔亮带。画面停住一小拍，远处鸟鸣退去，坑边几粒细石落完，巨体仍虚在焦点之外。','上方浅蓝灰云天转暖白，坑边米灰碎石在下缘模糊，薄尘退成浅暖灰层。','中央晨光穿雾后形成低角度暖白亮边，上方冷白云光仍托住背部暗面，整体保持虚焦软层。','鸟鸣余声渐退，几粒细石落坑，随后一段偏静的空地风声。',phase='state',node={'叙事阶段':'切回伏地武士，整体仍虚焦','武士.状态':'伏地不动，复起前一刻'},meaning='武士伏地虚焦节点保留，以短静止衔接局部复苏预兆。',characters=['鬼头武士'])
add('24_003',1.5,'16:9，武士背肩的局部特写，隆起肌块横跨画面中央，右侧轮廓与擦痕清楚；固定低侧机位，焦点由软到清落在背部隆起线。','武士背肩先在皮下般绷紧一小块，沿肌块边缘向两侧牵开，右侧轮廓短短抬起又压回；深色擦痕跟着弧面移过一点，几枚贴背的细灰被震落。焦点完全锐起来时，背部再抽动一下，低沉的受力声从巨体里传出。','背部外缘上方只有浅暖灰白云雾，下方背景完全被主体遮住。','暖白晨光沿背脊弧面拉出柔长亮带，冷白漫射在凹处保留冷灰层，擦痕与轮廓清楚。','两下低短的肌肉绷动声，细灰落石，风声在第二下后收薄。',phase='process',node={'叙事阶段':'武士背部抽动，复起预兆出现','武士.状态':'伏地背肩绷动'},meaning='从整体虚焦转到背肩清楚的抽动，原格短动线与隆起形落实为局部动作。',motion='背肩向上短抬再回压，尚未撑起全身。',ground='躯干仍伏在石坑，只有背部局部绷动。',characters=['鬼头武士'])
add('25_001',1,'16:9，董白侧脸极特写从画面右侧入框，圆眼与微张嘴位于中央偏右，左侧留武士所在的画外方向；固定机位。','董白原本看着青的眼珠骤然横移，眉毛抬起，唇缝松开；她头沿声音方向转过小角度，鬓发晚一拍扫过脸侧，视线立刻锁在武士方向。脸部动作停得很快，瞳孔仍缩成小点。','左侧空隙为浅暖灰天空，极淡蓝灰云纹在远层柔化。','晨光在脸侧添一线暖白，上方冷白漫射保留在黑发边缘，圆眼反光清楚。','武士方向的绷动余声先入，董白鬓发急擦一下，随后只留短吸气。',phase='reaction',node={'叙事阶段':'董白察觉武士动静','董白.位置':'仍搭肩扶着青，转头看向武士'},meaning='董白圆眼侧脸突转的原格反应保留，感知在复起全貌揭示之前。',characters=['董白'])
